#!/usr/bin/env python3
"""Validate storyboard JSON generated by real-person-short-drama-v3."""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path
from typing import Any, Dict, List, Mapping, Optional, Sequence, Set, Tuple


TOP_LEVEL_FIELDS = ["character", "scene", "item", "storyboard"]
STORYBOARD_FIELDS = ["name", "duration", "prompt", "character", "scene", "item"]
ASSET_FIELDS = ["name", "prompt"]
STYLE_LINE = "真人电影风格,画面不要出现任何文字，生成视频无BGM；"
SPACE_MASTER_PREFIX = "空间母版-"

ASSET_LABELS = {"character": "角色", "scene": "场景", "item": "物品"}
TOKEN_TO_FIELD = {"角色": "character", "场景": "scene", "物品": "item"}
TOKEN_RE = re.compile(r"@\[(角色|场景|物品)-([^\]]+)\]")
SCENE_TOKEN_RE = re.compile(r"@\[场景-[^\]]+\]")

SHOT_SCALES = (
    "远景",
    "全景",
    "中远景",
    "中全景",
    "中景",
    "近景",
    "特写",
    "大特写",
)
SHOT_SCALE_INDEX = {scale: index for index, scale in enumerate(SHOT_SCALES)}
SHOT_SCALE_PATTERN = "(?:" + "|".join(sorted(SHOT_SCALES, key=len, reverse=True)) + ")"
CAMERA_ANGLES = (
    "平视",
    "俯视",
    "仰拍",
    "低角度",
    "高角度",
    "侧面",
    "正面",
    "背面",
    "过肩",
    "主观视角",
)
CAMERA_ANGLE_PATTERN = "(?:" + "|".join(sorted(CAMERA_ANGLES, key=len, reverse=True)) + ")"

SHOT_LINE_RE = re.compile(r"^镜头(?P<number>\d+)：")
SHOT_HEADER_RE = re.compile(
    rf"^镜头(?P<number>\d+)：(?P<start>{SHOT_SCALE_PATTERN})，"
    rf"(?P<angle>{CAMERA_ANGLE_PATTERN})，(?P<camera>[^。]+)。"
)
DEST_SCALE_RE = re.compile(rf"至(?P<end>{SHOT_SCALE_PATTERN})")

CAMERA_MOVES = (
    "手持跟随",
    "固定机位",
    "推镜",
    "拉镜",
    "横移",
    "摇镜",
    "跟拍",
    "升镜",
    "降镜",
    "绕摄",
)
CAMERA_MOVE_RE = re.compile("|".join(sorted(CAMERA_MOVES, key=len, reverse=True)))
MOVING_START_RE = re.compile(r"先稳定|从[^，；。]+开始|起于")
MOVING_TRIGGER_RE = re.compile(
    r"(?:当|随着|待)[^；。]+?(?:时|后)(?:才)?开始|[^；。]+时(?:才)?开始|由[^；。]+触发"
)
MOVING_END_RE = re.compile(r"停稳|停在|停于|最终落在|结束于")

BRIDGE_TYPES = (
    "动作完成切",
    "反应切",
    "视线切",
    "物件切",
    "构图匹配切",
    "时空转场切",
)
BRIDGE_TYPE_PATTERN = "(?:" + "|".join(BRIDGE_TYPES) + ")"
IN_POINT_RE = re.compile(rf"开头承接(?P<type>{BRIDGE_TYPE_PATTERN})")
OUT_POINT_RE = re.compile(rf"结尾供(?P<type>{BRIDGE_TYPE_PATTERN})")

FORBIDDEN_INTERNAL_PATTERNS = (
    (re.compile(r"c\d{2},\d+s"), "内部 cNN 秒数"),
    (re.compile(r"\d+\s*[-–—~至]\s*\d+\s*(?:s|秒)"), "逐镜头精确时间段"),
    (re.compile(r"\((?:意图|起幅|落幅|空间|姿态):"), "内部导演分析标签"),
    (re.compile(r"主运镜:"), "内部主运镜标签"),
    (re.compile(r"B\d{3}"), "内部边界编号"),
    (re.compile(r"【(?:入点|出点):"), "内部入出点标签"),
)

FORBIDDEN_VAGUE_MODEL_PATTERNS = (
    (re.compile(r"电影感运镜|电影级运镜"), "空泛运镜词"),
    (re.compile(r"高级镜头语言|动态镜头"), "空泛镜头词"),
    (re.compile(r"增强(?:氛围|压迫感|情绪|电影感)"), "空泛意图词"),
    (re.compile(r"唯美光影|高级构图|氛围感(?:拉满|十足|强烈)"), "空泛视觉词"),
)

FORBIDDEN_NEGATIVE_SLOP_PATTERNS = (
    re.compile(r"(?:负面提示词|negative\s*prompt)\s*[:：]", re.IGNORECASE),
    re.compile(
        r"(?:不要|避免|禁止|无)(?:出现)?(?:画面)?"
        r"(?:模糊|变形|畸变|畸形|伪影|噪点|抖动|闪烁|跳变|崩坏|穿模|"
        r"多手|断手|额外手指|多余手指|少手指|重复人物|人物复制|脸部漂移|变脸)"
    ),
    re.compile(
        r"\b(?:no|avoid)\s+(?:blur|artifacts?|distortion|deformation|flicker|jitter|"
        r"extra fingers?|missing fingers?|duplicate (?:people|persons|characters)|face drift)\b",
        re.IGNORECASE,
    ),
)

QUOTED_SPEECH_RE = re.compile(r"“[^”]*”")


def load_json(path: Path) -> Tuple[Optional[Any], List[str]]:
    """Load UTF-8 JSON and return all file-level errors without raising."""
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        return None, [f"无法读取 JSON 文件 {path}: {exc}"]
    try:
        return json.loads(text), []
    except json.JSONDecodeError as exc:
        return None, [f"JSON 解析失败（第 {exc.lineno} 行第 {exc.colno} 列）: {exc.msg}"]


def _is_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _validate_assets(data: Mapping[str, Any], errors: List[str]) -> Dict[str, Set[str]]:
    declared: Dict[str, Set[str]] = {field: set() for field in ASSET_LABELS}
    for field, label in ASSET_LABELS.items():
        assets = data.get(field)
        if not isinstance(assets, list):
            errors.append(f"顶层 {field} 必须是数组")
            continue
        for index, asset in enumerate(assets):
            location = f"{field}[{index}]"
            if not isinstance(asset, dict):
                errors.append(f"{location} 必须是对象")
                continue
            if list(asset.keys()) != ASSET_FIELDS:
                errors.append(f"{location} 字段顺序必须为 {', '.join(ASSET_FIELDS)}")
            name = asset.get("name")
            prompt = asset.get("prompt")
            if not isinstance(name, str) or not name.strip():
                errors.append(f"{location}.name 必须是非空字符串")
            elif name in declared[field]:
                errors.append(f"{label}资产名称重复: {name}")
            else:
                declared[field].add(name)
            if not isinstance(prompt, str) or not prompt.strip():
                errors.append(f"{location}.prompt 必须是非空字符串")
    return declared


def _validate_scene_masters(
    data: Mapping[str, Any],
    declared: Mapping[str, Set[str]],
    errors: List[str],
) -> Tuple[Dict[str, str], Dict[str, Set[str]]]:
    """Validate scene assets named 空间母版-X and collect their dependency tokens."""
    masters: Dict[str, str] = {}
    used: Dict[str, Set[str]] = {field: set() for field in ASSET_LABELS}
    scenes = data.get("scene")
    if not isinstance(scenes, list):
        return masters, used
    for index, asset in enumerate(scenes):
        if not isinstance(asset, dict):
            continue
        name, prompt = asset.get("name"), asset.get("prompt")
        if not isinstance(name, str) or not name.startswith(SPACE_MASTER_PREFIX):
            continue
        base = name[len(SPACE_MASTER_PREFIX) :].strip()
        if not base:
            errors.append(f"scene[{index}] 空间母版名称必须在前缀后包含基础场景名")
            continue
        if base in masters:
            errors.append(f"基础场景“{base}”只能声明一个无状态后缀的空间母版")
        masters[base] = name
        if base not in declared["scene"]:
            errors.append(f"空间母版“{name}”缺少基础场景资产“{base}”")
        scene_dependencies: Set[str] = set()
        if isinstance(prompt, str):
            for token_type, token_name in TOKEN_RE.findall(prompt):
                field = TOKEN_TO_FIELD[token_type]
                used[field].add(token_name)
                if token_name not in declared[field]:
                    errors.append(
                        f"scene[{index}] 空间母版 prompt 的{ASSET_LABELS[field]}引用“{token_name}”"
                        "未在顶层资产中声明"
                    )
                if field == "scene":
                    scene_dependencies.add(token_name)
        if base not in scene_dependencies:
            errors.append(f"空间母版“{name}”的 prompt 必须引用 @[场景-{base}] 作为空间基底")
    return masters, used


def _validate_reference_array(
    shot: Mapping[str, Any],
    field: str,
    index: int,
    declared: Mapping[str, Set[str]],
    errors: List[str],
) -> Optional[Set[str]]:
    values = shot.get(field)
    if not isinstance(values, list):
        errors.append(f"storyboard[{index}].{field} 必须是数组")
        return None
    if any(not isinstance(value, str) or not value for value in values):
        errors.append(f"storyboard[{index}].{field} 只能包含非空字符串")
        return None
    value_set = set(values)
    if len(value_set) != len(values):
        errors.append(f"storyboard[{index}].{field} 不得包含重复名称")
    label = ASSET_LABELS[field]
    for value in values:
        if value not in declared[field]:
            errors.append(f"storyboard[{index}] {label}引用“{value}”未在顶层资产中声明")
    return value_set


def _validate_no_internal_syntax(prompt: str, index: int, errors: List[str]) -> None:
    for pattern, label in FORBIDDEN_INTERNAL_PATTERNS:
        if pattern.search(prompt):
            errors.append(f"storyboard[{index}].prompt 不得包含{label}，应编译为 Seedance 镜头N 格式")

    instruction_text = QUOTED_SPEECH_RE.sub("“”", prompt)
    for pattern, label in FORBIDDEN_VAGUE_MODEL_PATTERNS:
        if pattern.search(instruction_text):
            errors.append(
                f"storyboard[{index}].prompt 不得包含{label}，"
                "请改写为物理动作、光源、触发和可见结果"
            )

    if any(pattern.search(instruction_text) for pattern in FORBIDDEN_NEGATIVE_SLOP_PATTERNS):
        errors.append(
            f"storyboard[{index}].prompt 不得包含普通负面缺陷词或独立负面提示词清单，"
            "请改写为正向状态锁或针对当前动作顺序的短局部约束"
        )


def _parse_shot_lines(prompt: str, index: int, errors: List[str]) -> List[str]:
    lines = prompt.splitlines()
    if not lines or lines[0] != STYLE_LINE:
        errors.append(f"storyboard[{index}].prompt 首行必须是固定风格串")
    shot_lines = lines[1:] if lines else []
    if not shot_lines:
        errors.append(f"storyboard[{index}].prompt 至少需要一个镜头N 子镜头")
        return []

    actual_numbers: List[int] = []
    for line_number, line in enumerate(shot_lines, start=2):
        match = SHOT_LINE_RE.match(line)
        if match is None:
            errors.append(f"storyboard[{index}].prompt 第 {line_number} 行必须以镜头N：开头")
        else:
            actual_numbers.append(int(match.group("number")))
    expected_numbers = list(range(1, len(shot_lines) + 1))
    if len(actual_numbers) != len(shot_lines) or actual_numbers != expected_numbers:
        errors.append(f"storyboard[{index}] 镜头编号必须从镜头1连续递增")
    return shot_lines


def _validate_camera_physics(
    location: str,
    line: str,
    header: re.Match[str],
    errors: List[str],
) -> Optional[str]:
    camera_spec = header.group("camera")
    move_matches = CAMERA_MOVE_RE.findall(camera_spec)
    if len(move_matches) != 1:
        errors.append(
            f"{location} 镜头头部必须且只能使用一种标准主运镜: {', '.join(CAMERA_MOVES)}"
        )
        return None

    move = move_matches[0]
    start_scale = header.group("start")
    destinations = DEST_SCALE_RE.findall(camera_spec)

    if move in {"推镜", "拉镜"}:
        if len(destinations) != 1:
            errors.append(f"{location} {move}必须在镜头头部写明唯一“至结束景别”")
        else:
            end_scale = destinations[0]
            delta = SHOT_SCALE_INDEX[end_scale] - SHOT_SCALE_INDEX[start_scale]
            if abs(delta) > 2:
                errors.append(f"{location} 单镜景别变化不得超过两级")
            if move == "推镜" and delta <= 0:
                errors.append(f"{location} 推镜必须由松景别进入紧景别")
            if move == "拉镜" and delta >= 0:
                errors.append(f"{location} 拉镜必须由紧景别退出到松景别")
    elif destinations:
        errors.append(f"{location} {move}应保持同级景别，不得写“至结束景别”")

    if move != "固定机位":
        if MOVING_START_RE.search(line) is None:
            errors.append(f"{location} 移动镜必须写明稳定的起始构图")
        if MOVING_TRIGGER_RE.search(line) is None:
            errors.append(f"{location} 移动镜必须由可见剧情动作触发")
        if MOVING_END_RE.search(line) is None:
            errors.append(f"{location} 移动镜必须写明停稳的构图终点")
    return move


def _validate_model_shots(
    shot_lines: Sequence[str], index: int, errors: List[str]
) -> List[Optional[str]]:
    moves: List[Optional[str]] = []
    for line_index, line in enumerate(shot_lines, start=1):
        location = f"storyboard[{index}] 镜头{line_index}"
        header = SHOT_HEADER_RE.match(line)
        if header is None:
            errors.append(
                f"{location} 必须使用“镜头N：景别，机位，标准主运镜。”头部"
            )
            moves.append(None)
            continue
        body = line[header.end() :]
        if "画面中" not in body:
            errors.append(
                f"{location} 必须在摄影机头部后使用“画面中”写出可见画面描述，"
                "不能只写主体动作"
            )
        if SCENE_TOKEN_RE.search(body) is None:
            errors.append(
                f"{location} 必须在本镜画面描述中写出 @[场景-名称] token 和具体可见区域"
            )
        moves.append(_validate_camera_physics(location, line, header, errors))

    if len(shot_lines) >= 2 and "固定机位" not in moves:
        errors.append(f"storyboard[{index}] 含两镜以上时至少需要一个固定机位稳定画面")
    if moves.count("推镜") > 1:
        errors.append(f"storyboard[{index}] 每个分镜最多使用一次推镜")
    if shot_lines and "保持半秒" not in shot_lines[-1]:
        errors.append(f"storyboard[{index}] 末镜必须写明“保持半秒”安全尾帧")
    return moves


def _collect_natural_points(
    lines: Sequence[str], pattern: re.Pattern[str]
) -> List[Tuple[int, str]]:
    points: List[Tuple[int, str]] = []
    for line_index, line in enumerate(lines):
        for match in pattern.finditer(line):
            points.append((line_index, match.group("type")))
    return points


def _validate_storyboard_bridges(
    storyboards: Sequence[Sequence[str]], errors: List[str]
) -> None:
    total = len(storyboards)
    incoming: List[Optional[str]] = [None] * total
    outgoing: List[Optional[str]] = [None] * total

    for index, lines in enumerate(storyboards):
        if not lines:
            continue
        in_points = _collect_natural_points(lines, IN_POINT_RE)
        out_points = _collect_natural_points(lines, OUT_POINT_RE)
        raw_in_count = sum(line.count("开头承接") for line in lines)
        raw_out_count = sum(line.count("结尾供") for line in lines)

        if raw_in_count != len(in_points):
            errors.append(f"storyboard[{index}] 入点类型无效；只允许规定的六类自然语言切点")
        if raw_out_count != len(out_points):
            errors.append(f"storyboard[{index}] 出点类型无效；只允许规定的六类自然语言切点")

        if index == 0:
            if in_points:
                errors.append("storyboard[0] 首个分镜不得包含“开头承接”")
        elif len(in_points) != 1 or in_points[0][0] != 0:
            errors.append(f"storyboard[{index}] 只允许在首个镜头放一个自然语言入点")
        else:
            incoming[index] = in_points[0][1]

        if index == total - 1:
            if out_points:
                errors.append(f"storyboard[{index}] 末个分镜不得包含“结尾供”")
        elif len(out_points) != 1 or out_points[0][0] != len(lines) - 1:
            errors.append(f"storyboard[{index}] 只允许在末个镜头放一个自然语言出点")
        else:
            outgoing[index] = out_points[0][1]

    for index in range(total - 1):
        if outgoing[index] is not None and incoming[index + 1] is not None:
            if outgoing[index] != incoming[index + 1]:
                errors.append(
                    f"storyboard[{index}] 出点与 storyboard[{index + 1}] 入点类型不闭环"
                )


def validate_storyboard(data: Any, duration_sec: int) -> List[str]:
    """Return every structural validation error found in a storyboard document."""
    errors: List[str] = []
    if not _is_int(duration_sec) or duration_sec < 4:
        return ["duration_sec 必须是大于等于 4 的整数"]
    if not isinstance(data, dict):
        return ["JSON 顶层必须是对象"]
    if list(data.keys()) != TOP_LEVEL_FIELDS:
        errors.append(f"顶层字段顺序必须为 {', '.join(TOP_LEVEL_FIELDS)}")

    declared = _validate_assets(data, errors)
    scene_masters, master_dependencies = _validate_scene_masters(data, declared, errors)
    used_globally: Dict[str, Set[str]] = {field: set() for field in ASSET_LABELS}
    for field in ASSET_LABELS:
        used_globally[field].update(master_dependencies[field])
    storyboards = data.get("storyboard")
    if not isinstance(storyboards, list):
        errors.append("顶层 storyboard 必须是数组")
        return errors
    if not storyboards:
        errors.append("顶层 storyboard 不得为空")
        return errors

    parsed_storyboards: List[List[str]] = []
    logical_scene_storyboards: Dict[str, Set[int]] = {}
    storyboard_scene_tokens: List[Set[str]] = []
    for index, shot in enumerate(storyboards):
        location = f"storyboard[{index}]"
        if not isinstance(shot, dict):
            errors.append(f"{location} 必须是对象")
            parsed_storyboards.append([])
            storyboard_scene_tokens.append(set())
            continue
        if list(shot.keys()) != STORYBOARD_FIELDS:
            errors.append(f"{location} 分镜字段顺序必须为 {', '.join(STORYBOARD_FIELDS)}")

        name = shot.get("name")
        if not isinstance(name, str) or not name:
            errors.append(f"{location}.name 必须是非空字符串")
        elif len(name) > 15:
            errors.append(f"{location}.name 不得超过 15 字")

        duration = shot.get("duration")
        if not _is_int(duration):
            errors.append(f"{location}.duration 必须是整数")
        elif not 4 <= duration <= duration_sec:
            position = "非末镜" if index < len(storyboards) - 1 else "末镜"
            errors.append(f"{location} {position} duration 必须在 4..{duration_sec} 范围内")

        prompt = shot.get("prompt")
        if not isinstance(prompt, str):
            errors.append(f"{location}.prompt 必须是字符串")
            shot_lines: List[str] = []
        else:
            _validate_no_internal_syntax(prompt, index, errors)
            shot_lines = _parse_shot_lines(prompt, index, errors)
            _validate_model_shots(shot_lines, index, errors)
            if shot_lines and "不出现任何文字字幕" not in shot_lines[-1]:
                errors.append(f"{location} 最后一个子镜头必须包含“不出现任何文字字幕”")
        parsed_storyboards.append(shot_lines)

        reference_sets: Dict[str, Optional[Set[str]]] = {}
        for field in ASSET_LABELS:
            reference_sets[field] = _validate_reference_array(
                shot, field, index, declared, errors
            )

        tokens_by_field: Dict[str, Set[str]] = {field: set() for field in ASSET_LABELS}
        if isinstance(prompt, str):
            for token_type, token_name in TOKEN_RE.findall(prompt):
                field = TOKEN_TO_FIELD[token_type]
                tokens_by_field[field].add(token_name)

        for field, label in ASSET_LABELS.items():
            token_names = tokens_by_field[field]
            references = reference_sets[field]
            used_globally[field].update(token_names)
            for token_name in token_names:
                if token_name not in declared[field]:
                    errors.append(f"{location} {label}引用“{token_name}”未在顶层资产中声明")
            if references is not None and references != token_names:
                missing = sorted(token_names - references)
                extra = sorted(references - token_names)
                details = []
                if missing:
                    details.append(f"数组缺少 {missing}")
                if extra:
                    details.append(f"数组多出 {extra}")
                errors.append(
                    f"{location}.{field} 引用数组与 prompt token 不闭环: " + "；".join(details)
                )

        scene_tokens = tokens_by_field["scene"]
        storyboard_scene_tokens.append(scene_tokens)
        for scene_name in scene_tokens:
            logical_name = (
                scene_name[len(SPACE_MASTER_PREFIX) :]
                if scene_name.startswith(SPACE_MASTER_PREFIX)
                else scene_name
            )
            logical_scene_storyboards.setdefault(logical_name, set()).add(index)
        for base, master in scene_masters.items():
            if base in scene_tokens and master in scene_tokens:
                errors.append(
                    f"{location} 已引用空间母版“{master}”，不得同时发送基础空景“{base}”"
                )

    _validate_storyboard_bridges(parsed_storyboards, errors)
    for base, indexes in logical_scene_storyboards.items():
        if len(indexes) < 2:
            continue
        master = scene_masters.get(base)
        if master is None:
            errors.append(
                f"基础场景“{base}”跨 {len(indexes)} 个 storyboard，必须声明“{SPACE_MASTER_PREFIX}{base}”"
            )
            continue
        for index in sorted(indexes):
            if master not in storyboard_scene_tokens[index]:
                errors.append(
                    f"storyboard[{index}] 属于跨片段场景“{base}”，必须只引用空间母版“{master}”"
                )
    for field, label in ASSET_LABELS.items():
        for unused in sorted(declared[field] - used_globally[field]):
            errors.append(f"顶层{label}资产“{unused}”未被任何分镜引用")
    return errors


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("json_file", type=Path, help="待校验的 UTF-8 JSON 文件")
    parser.add_argument(
        "--duration-sec",
        type=int,
        required=True,
        help="分镜主切割时长上限（秒；每个分镜为 4..该值）",
    )
    return parser


def main(argv: Optional[Sequence[str]] = None) -> int:
    args = build_parser().parse_args(argv)
    data, load_errors = load_json(args.json_file)
    if load_errors:
        for error in load_errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 2
    errors = validate_storyboard(data, args.duration_sec)
    if errors:
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1
    print("OK: storyboard JSON is valid")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
